function getNestedProperty(obj, path) {
    const keys = path.split('.');
    let currentObj = obj;

    for (let i = 0; i < keys.length - 1; i++) {
        if (!currentObj || !currentObj[keys[i]]) {
            throw new Error(`Path '${path}' does not match any property.`);
